// ===== TURN ENGINE =====
function spdOf(m){let s=SP[m.s].s;if(m.slow>0)s*=.5;if(SP[m.s].tags.coldslow&&seasonIdx()===3)s*=.45;if(m.dz==='mania')s*=1.2;return s}
function advance(cost){if(G.over)return;cost=cost===undefined?100:cost;const p=G.p;rebuild();let c=cost*100/(70+eff('spd')*6);G.acc+=c;
 if(!p.fx.tstop){for(const m of RT.act.slice()){if(G.over)break;if(m.dead||L.cr.indexOf(m)<0)continue;m.en=(m.en||0)+c*spdOf(m)/100;let g=0;while(m.en>=100&&!G.over&&g++<4){m.en-=100;aiAct(m)}}}
 while(G.acc>=100&&!G.over){G.acc-=100;envTick()}
 if(RT.forceWait&&!G.over){const n=RT.forceWait;RT.forceWait=0;msg('You lose '+n+' turns.','bad');for(let i=0;i<n&&!G.over;i++)advance(100)}
 if(RT.later&&!G.over){const l=RT.later;RT.later=null;l.forEach(f=>f())}
 RT.arsonT=0;rebuild();computeFOV();if(G.turn%5===0)saveGame()}
function actWait(){advance(100)}
function toggleSneak(){G.p.sneak=!G.p.sneak;msg(G.p.sneak?'You move quietly. Slower, but harder to notice.':'You stop sneaking.','hint')}
function actMove(dx,dy){const p=G.p;if(G.over)return null;if(p.dom>0&&chance(.45)){const d=pick(DIRS);dx=d[0];dy=d[1];msg('Your legs do not obey you.','bad')}
 const nx=p.x+dx,ny=p.y+dy;if(!inb(L,nx,ny))return null;const e=at(nx,ny);for(let i=0;i<8;i++)if(DIRS[i][0]===dx&&DIRS[i][1]===dy)p.face=i;
 if(e){if(e.hidden&&!visible(nx,ny)){}if(e.ally||e.charm>0){swapWith(e,nx,ny);return null}if(hostile(e,p)||e.sleep>0&&e.fac!=='free'||SP[e.s].tags.prey){attackPlayerHit(e);return null}return{sheet:talkableOrNote(e)}}
 const d=tdef(nx,ny);if(d.k==='door'){tset(nx,ny,'dooropen');advance(60);return null}if(d.k==='locked'){msg('It is locked.','warn');return null}if(d.gate){msg('The '+d.n+' is locked.','warn');return null}
 if(!d.p&&!d.swim){if(d.k==='sea')msg('The open sea is too far to swim.','warn');else if(d.chop||d.mine||d.k==='well'||d.store||d.forge||d.arcane)return{tile:{x:nx,y:ny}};return null}
 if(L.fire[IX(nx,ny)]&&!p.fx.confirmFire){msg('You step into the flames!','bad')}
 const k0=IX(p.x,p.y);p.x=nx;p.y=ny;G.stats.tiles++;let cost=100*(d.m||1);if(d.swim){cost=220;if(p.torch>0){p.torch=0;msg('Your torch goes out.','warn')}msg('You swim. Your powder and torches get soaked.','warn');p.fx.wet={t:15};p.loaded=false}if(d.water)p.fx.wet={t:8};if(p.sneak)cost*=1.35;
 if(p.fx.slipped)delete p.fx.slipped;if(d.trap){if(d.k==='pit'){msg('You fall in a pit.','bad');hurt(p,3,null,'a pit');RT.forceWait=2}else if(d.k==='spikes'){hurt(p,8,null,'spikes');tset(nx,ny,'grass')}else if(d.k==='snare'){msg('A snare catches your ankle.','bad');RT.forceWait=3;tset(nx,ny,'grass')}}
 if(d.sticky){if(d.k==='tar'){msg('Tar drags at your feet.','warn');cost*=1.3}}if(d.spiky)hurt(p,1,null,'cactus');if(d.icy&&chance(.1)){const q=[dx,dy];if(!at(nx+q[0],ny+q[1])&&tdef(nx+q[0],ny+q[1]).p){p.x+=q[0];p.y+=q[1];msg('You slip on the ice.','warn')}}if(d.k==='thinice'&&chance(.015))meltTile(p.x,p.y);if(d.warm&&p.hp<p.mh&&chance(.4))p.hp++;
 const a=p.eq.a&&idef(p.eq.a);let nr=p.sneak?1:(a&&a.noisy?7:(tdef(nx,ny).k==='drift'||tdef(nx,ny).k==='sand'?5:4));noise(p.x,p.y,nr,'p');
 // tile notes
 const its=L.items[IX(p.x,p.y)];if(its&&its.length){const coin=its.filter(i=>i.k==='coins');coin.forEach(c=>{giveItem(c);its.splice(its.indexOf(c),1)});if(its.length)msg('Here: '+its.slice(0,3).map(iname).join(', ')+(its.length>3?' and more':'')+'.','hint');else delete L.items[IX(p.x,p.y)]}
 advance(cost);return null}
function talkableOrNote(e){if(SP[e.s].tags.talks)return talkSheet(e);msg(SP[e.s].n+' is in the way.','hint');return actionSheetFor(e.x,e.y)}
function swapWith(e,nx,ny){const p=G.p;const ox=p.x,oy=p.y;p.x=nx;p.y=ny;RT.occ.delete(IX(nx,ny));e.x=ox;e.y=oy;RT.occ.set(IX(ox,oy),e);advance(100)}
function attackPlayerHit(t){const p=G.p;if(!hostile(t,p)&&SP[t.s].tags.person)crime('assault',t);meleeHit(p,t);if(p.fx.invis)delete p.fx.invis;advance(100)}
function unaware(t){return t.sleep>0||(t.alert<2&&!(t.grudge&&t.grudge.p))}
function stealthPct(t,base){const hpPen=Math.min(40,t.mh*.5);let v=base+eff('sth')*8-hpPen+(t.sleep>0?30:0)+(G.p.sneak?10:0);if(isNight())v+=5;if(idef(G.p.eq.w).quiet)v+=10;if(G.wx.k==='fog')v+=5;return clamp(Math.round(v),5,97)}
function afterStealth(t,killed){const near=RT.act.filter(o=>o!==t&&!o.sleep&&(o.fac===t.fac)&&dist(o.x,o.y,t.x,t.y)<=7);const seen=near.some(o=>dist(o.x,o.y,G.p.x,G.p.y)<=6&&los(o.x,o.y,G.p.x,G.p.y)&&chance(.45-eff('sth')*.03));if(!near.length)return;if(seen){near.forEach(o=>{o.alert=2;o.lastSeen={x:G.p.x,y:G.p.y}});msg('You were seen!','warn');crime(killed?'murder':'assault',t)}else{near.forEach(o=>{o.confused=ri(5,9);o.alert=1;o.lastSeen=null});msg('No one saw you. Confusion spreads: "Who\'s there? WHO DID THAT?"','good');story('A silent '+(killed?'kill':'takedown')+' sent '+near.length+' '+FAC[t.fac].n+' into a blind panic.',2);gainXP(4)}}
function doStealthKill(t){const pct=stealthPct(t,25);if(chance(pct/100)){msg('You kill '+SP[t.s].n+' before it can make a sound.','kill');if(t.aegis){hurt(t,1,G.p);return advance(100)}t.hp=0;die(t,G.p,'stealth');afterStealth(t,true)}else{msg('Your strike is not clean.','warn');meleeHit(G.p,t);t.alert=2;afterStealth(t,false)}advance(100)}
function doKnockout(t){const pct=stealthPct(t,40);if(chance(pct/100)){if(t.aegis){msg('The Aegis throws you back.','warn')}else{t.sleep=80;t.ko=1;G.stats.knockouts++;msg(SP[t.s].n+' goes limp. Unconscious, not dead.','good');gainXP(Math.max(2,SP[t.s].xp>>1));afterStealth(t,false)}}else{msg('Your grip slips. '+SP[t.s].n+' whirls around!','warn');t.sleep=0;t.alert=2;(t.grudge=t.grudge||{}).p=1;crime('assault',t)}advance(100)}
function doPickpocket(t){const pct=clamp(Math.round(20+eff('sth')*6+eff('spd')*2+(t.sleep>0?35:0)),5,97);if(chance(pct/100)){const got=[];if(t.coins){G.p.coins+=t.coins;got.push(t.coins+' coins');t.coins=0}const loot=t.inv.slice();if(loot.length){const it=loot.find(i=>i.k.startsWith('piece_')||i.k==='key_gate')||pick(loot);t.inv.splice(t.inv.indexOf(it),1);giveItem(it,true);got.push(iname(it));afterGain(it)}msg(got.length?'You lift '+got.join(' and ')+' unnoticed.':'Their pockets are empty.','good');G.stats.thefts++;gainXP(3);if(got.some(s=>s.includes('Shard')))story('Picked the shard right off '+SP[t.s].n+'\'s belt.',3)}else{msg(SP[t.s].n+' catches your hand!','bad');t.sleep=0;t.alert=2;(t.grudge=t.grudge||{}).p=1;crime('theft',t)}advance(100)}
function doSpike(t,k){const d=ITEMS[k];takeItem(k);const sp=d.spike;msg('You slip '+d.n.toLowerCase()+' into '+SP[t.s].n+"'s drink.",'good');if(sp==='sleep'){t.sleep=70;t.ko=1;G.stats.knockouts++;if(t.aegis)msg('The Aegis burns the draught away before it does anything.','warn')}else if(sp==='poison'){if(!t.aegis){t.poison=25;t.poisonBy='p'}}else if(sp==='mania'){if(!t.aegis){t.dz='mania';t.dzT=240;story('Dosed '+SP[t.s].n+' with Red Mania.',2);G.flags.mania=G.flags.mania||G.turn}}else if(sp==='zombie'){if(!t.aegis){t.dz='zombie';t.dzT=40;story('Poisoned '+SP[t.s].n+' with the Grey Walk.',3);G.flags.grey=G.flags.grey||G.turn}}G.stats.thefts++;advance(100)}
// shooting
function canShoot(){const w=idef(G.p.eq.w);return w.rng?w:null}
function shootPct(t){const w=idef(G.p.eq.w),dd=dist(G.p.x,G.p.y,t.x,t.y);return clamp(Math.round(62+(eff('agi')-5)*6-dd*2+(t.sleep>0?25:0)),5,97)}
function firstOnLine(x0,y0,x1,y1){let dx=Math.abs(x1-x0),dy=Math.abs(y1-y0),sx=x0<x1?1:-1,sy=y0<y1?1:-1,e=dx-dy,x=x0,y=y0;while(!(x===x1&&y===y1)){const e2=2*e;if(e2>-dy){e-=dy;x+=sx}if(e2<dx){e+=dx;y+=sy}const t=at(x,y);if(t&&!isP(t))return t;const d=tdef(x,y);if(d.boom)return{barrel:1,x,y};if(d.o&&!(x===x1&&y===y1))return{wall:1,x,y}}return null}
function doShoot(x,y){const p=G.p,w=canShoot();if(!w)return;if(w.gun){if(!p.loaded&&!w.norld){msg('Reload first.','warn');return}if(w.norld&&!hasItem('shot')){msg('You are out of shot.','warn');return}if(w.norld)takeItem('shot');p.loaded=false;if((raining()&&outdoors(p.x,p.y)||p.fx.wet)&&chance(.3)){msg('Damp powder. The gun only fizzes.','warn');advance(100);return}}else if(w.usesStone){if(!hasItem('stone')){msg('You need stones for a sling.','warn');return}takeItem('stone')}
 const hit=firstOnLine(p.x,p.y,x,y);RT.fxq.push({type:'shot',x:p.x,y:p.y,x2:x,y2:y});if(w.gun&&w.ench!=='silence'){noise(p.x,p.y,14,'p');if(L.id==='world'&&regionAt(p.x,p.y)===RM&&seasonIdx()===3&&chance(.35))avalanche(p.x,p.y)}
 if(hit&&hit.barrel){msg('The shot finds the powder barrel.','warn');tset(hit.x,hit.y,'rubble');explode(hit.x,hit.y,3,p)}else if(hit&&!hit.wall){const t=hit;const pct=shootPct(t);if(unaware(t)&&SP[t.s].tags.person)crime('murder',t);if(chance(pct/100)){let dm=(w.d||3)+ri(0,Math.floor(eff('agi')/2))-(SP[t.s].ar||0);if(unaware(t))dm=Math.round(dm*1.5);msg('Your shot hits '+SP[t.s].n+' for '+dm+'.','');applyEnch(w,t);if(w.ench==='leech')p.hp=Math.min(p.mh,p.hp+Math.ceil(dm/2));hurt(t,Math.max(1,dm),p,w.ench==='mercy'?'mercy':'gunshot')}else{msg('Your shot misses.','');t.alert=2}}else{const t=at(x,y);const dd=tdef(x,y);if(w.gun&&dd.f&&chance(.1))ignite(x,y,1)}
 advance(100)}
function doReload(){const p=G.p,w=canShoot();if(!w||!w.gun)return;if(p.loaded){msg('Already loaded.','hint');return}if(!takeItem('shot')){msg('You have no powder and shot.','warn');return}p.loaded=true;msg('You ram home a charge.','');advance(120)}
function reachable(x,y,r){return dist(G.p.x,G.p.y,x,y)<=r&&(r<=1||los(G.p.x,G.p.y,x,y))}

// ===== SPELLS =====
function mindResisted(t,power){const d=SP[t.s];if(t.aegis)return true;if(d.tags.mindless&&!d.tags.undead)return true;const ch=clamp(power*9-t.mh*.4+30,8,97);return !chance(ch/100)}
function castSpell(s,c,x,y){const pl=isP(c);const pw=pl?eff('int'):5;const t=at(x,y);const name=pl?'You':SP[c.s].n;RT.fxq.push({type:'bolt',x:c.x,y:c.y,x2:x,y2:y,s});const seen=pl||visible(c.x,c.y)||(t&&isP(t));
 if(seen&&!pl)msg(name+' casts '+SPELLS[s].n+'!','warn');
 switch(s){
 case 'firebolt':{if(t)t.burning=Math.max(t.burning||0,4);if(t&&!isP(t))t.fireBy=pl?1:0;if(t){hurt(t,5+pw,pl?c:c,'fire')}ignite(x,y,pl?1:0);if(tdef(x,y).icy)meltTile(x,y);if(tdef(x,y).water&&!t)addGas(x,y,'steam',4);noise(x,y,6,pl?'p':null);break}
 case 'frost':{if(t){hurt(t,3+(pw>>1),c,'frost');if(!isP(t)){t.slow=8;t.burning=0}else{t.burning=0}}for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){freezeTile(x+dx,y+dy,40);delete L.fire[IX(x+dx,y+dy)]}break}
 case 'shock':{shockFrom(x,y,4+pw,c,t);break}
 case 'heal':{if(pl){c.hp=Math.min(c.mh,c.hp+8+pw*2);msg('Warmth knits your wounds.','good')}break}
 case 'sleep':{if(t){if(isP(t)){if(!chance((eff('int')*8+10)/100)){msg('Your eyelids slam shut.','bad');RT.forceWait=3}else msg('You shake off the sleep spell.','good')}else if(!SP[t.s].tags.undead&&!mindResisted(t,pw)){t.sleep=24;t.ko=1;if(pl)msg(SP[t.s].n+' sinks to the ground.','good')}else if(pl)msg(SP[t.s].n+' resists.','warn')}break}
 case 'charm':{if(t){if(isP(t)){if(!chance((eff('int')*8+10)/100)){p_dom(5)}}else if(pl){if((SP[t.s].tags.animal||t.mh<=15)&&!mindResisted(t,pw)){t.charm=70;t.alert=0;delete t.grudge;msg(SP[t.s].n+' looks at you with sudden devotion.','good');gainXP(3)}else msg('It does not take.','warn')}else if(!mindResisted(t,3)){t.mindfac=c.fac;t.mindT=25;t.alert=0}}break}
 case 'fear':{if(t){if(isP(t)){if(!chance((eff('int')*7+10)/100))p_dom(3)}else if(!mindResisted(t,pw)||!SP[t.s].tags.brave){t.fear=12;if(pl)msg(SP[t.s].n+' flees in terror.','good')}}break}
 case 'brainwash':{if(t){if(isP(t)){if(!chance((eff('int')*7+5)/100)){p_dom(8);msg(name+' reaches into your mind!','bad');story(name+' seized your mind.',2)}else msg('You push '+name+' out of your head.','good')}else if(pl){if(t.id===G.kingId&&!t.aegis&&!mindResisted(t,pw)){msg('The king\'s eyes go flat. He belongs to you now.','story');endGame('puppet');return}if(SP[t.s].tags.person&&!mindResisted(t,pw)){t.charm=45;t.mindOld=t.fac;t.alert=0;t.grudge={};delete t.truce;msg(SP[t.s].n+' turns to look at its friends. It is smiling.','good');story('Brainwashed '+SP[t.s].n+' into fighting its own kin.',2);G.stats.brainwash++;gainXP(6);crime('mind-theft',t)}else msg(SP[t.s].n+' resists.','warn')}else if(!mindResisted(t,4)&&!t.aegis){t.mindfac=c.fac;t.mindT=30;t.alert=0;t.grudge={};if(visible(x,y))msg(SP[t.s].n+' turns on its own side.','warn')}}break}
 case 'raise':raiseAt(x,y,c);break;
 case 'blink':{if(pl){if(tdef(x,y).p&&!at(x,y)){c.x=x;c.y=y;msg('Space folds. You are elsewhere.','good')}}else{const q=findTile(c,5,(dd,a,b)=>dd.p&&!at(a,b));if(q){moveC(c,q.x,q.y)}}break}
 case 'gust':{for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++){const nx=x+dx,ny=y+dy;const g=L.gas[IX(nx,ny)];if(g)delete L.gas[IX(nx,ny)];const e=at(nx,ny);if(e&&e!==c)pushEnt(e,c.x,c.y,3,c);if(L.fire[IX(nx,ny)]&&chance(.5)){delete L.fire[IX(nx,ny)];const w=pick(DIRS);ignite(nx+w[0]*2,ny+w[1]*2,pl?1:0)}}noise(x,y,5,pl?'p':null);break}
 }}
function p_dom(n){G.p.dom=Math.max(G.p.dom,n);msg('Your body stops obeying you.','bad')}
function pushEnt(e,fx,fy,n,src){const dx=Math.sign(e.x-fx)||0,dy=Math.sign(e.y-fy)||0;for(let i=0;i<n;i++){const nx=e.x+dx,ny=e.y+dy;const d=tdef(nx,ny);if(!inb(L,nx,ny)||at(nx,ny)||(!d.p&&!d.swim)){if(i>0)hurt(e,3,src,'impact');return}if(isP(e)){e.x=nx;e.y=ny}else{const k=IX(e.x,e.y);RT.occ.delete(k);e.x=nx;e.y=ny;RT.occ.set(IX(nx,ny),e)}if(d.swim&&!isP(e)&&!SP[e.s].tags.flier){if(visible(nx,ny))msg(SP[e.s].n+' is thrown into deep water.','good');hurt(e,e.hp+1,src,'fall');return}if(d.trap&&!isP(e))trap(e,nx,ny)}}
function shockFrom(x,y,dm,c,t){const seen=new Set(),hit=[];const start=IX(x,y);seen.add(start);const q=[[x,y]];let h=0;while(h<q.length&&seen.size<60){const [a,b]=q[h++];const e=at(a,b);if(e&&e!==c&&!hit.includes(e))hit.push(e);for(const[dx,dy]of DIRS){const nx=a+dx,ny=b+dy;if(!inb(L,nx,ny))continue;const k=IX(nx,ny);if(seen.has(k))continue;const dd=tdef(nx,ny);const oc=at(nx,ny);if(dd.water||(oc&&(oc.wet>0||(isP(oc)&&oc.fx.wet)))||tdef(a,b).water&&oc){seen.add(k);q.push([nx,ny])}}}if(t&&!hit.includes(t))hit.push(t);RT.fxq.push({type:'burst',x,y,e:'shock'});hit.forEach(e=>{const wet=isP(e)?!!e.fx.wet:e.wet>0;hurt(e,wet?dm*2:dm,c,'lightning');if(!isP(e))e.stun=1;if(visible(e.x,e.y))msg('Lightning arcs through '+(isP(e)?'you':SP[e.s].n)+'!',isP(e)?'bad':'good')});if(hit.length>2&&isP(c))story('A single bolt of lightning ran through '+hit.length+' creatures in the water.',2);noise(x,y,8,isP(c)?'p':null)}
function raiseAt(x,y,c){const k=IX(x,y),its=L.items[k];if(!its)return false;const cp=its.find(i=>i.k==='corpse');if(!cp)return false;its.splice(its.indexOf(cp),1);if(!its.length)delete L.items[k];const sp=SP[cp.sp]||SP.villager;const z=spawn('undeadthrall',x,y,{life:isP(c)?300:0,fac:isP(c)?'player':(c.fac),ally:isP(c)?1:0,mh:Math.max(8,sp.hp*.7|0),hp:Math.max(8,sp.hp*.7|0)},L);RT.occ.set(k,z);z.origin=cp.sp;if(visible(x,y))msg(sp.n+' corpse lurches upright.',isP(c)?'good':'warn');if(isP(c)){G.stats.raised++;gainXP(4);story('Raised a '+sp.n+' from the dead.',2);crime('necromancy',{fac:'free'})}return true}
function spellCost(e){let c=0;(e.fx||[]).forEach(f=>{const d=EFFECTS[f.e];c+=d.c*f.mag*(1+f.area*.8)*(1+f.dur/15)});return Math.max(1,Math.round(c/(1+eff('int')*.07)))}
function customCost(sp){return spellCost(sp)}
function targetsIn(x,y,r){const o=[];for(let dy=-r;dy<=r;dy++)for(let dx=-r;dx<=r;dx++){if(Math.hypot(dx,dy)>r+.4)continue;const e=at(x+dx,y+dy);if(e)o.push(e)}return o}
function castCustom(sp,x,y){const p=G.p;const cost=customCost(sp);if(p.mp<cost){const blood=cost-p.mp;if(p.hp<=blood){msg('Casting this now would kill you.','bad');return false}p.mp=0;p.hp-=blood;msg('You pay the difference in blood: '+blood+' health.','bad')}else p.mp-=cost;RT.fxq.push({type:'bolt',x:p.x,y:p.y,x2:x,y2:y,s:'custom'});msg('You cast '+sp.name+'.','good');sp.fx.forEach(f=>applyEffect(f.e,f.mag,f.area,f.dur,p,x,y));noise(x,y,6,'p');advance(100);return true}
function applyEffect(e,mag,area,dur,c,x,y){const p=G.p,def=EFFECTS[e];const tg=def.t==='self'?[p]:targetsIn(x,y,area);
 const each=(fn)=>{tg.forEach(t=>{if(t!==c||def.t==='self')fn(t)})};
 const tiles=(fn)=>{for(let dy=-area;dy<=area;dy++)for(let dx=-area;dx<=area;dx++){if(Math.hypot(dx,dy)>area+.4)continue;fn(x+dx,y+dy)}};
 switch(e){
 case 'fire':each(t=>{hurt(t,mag,c,'fire');if(t.hp>0){t.burning=Math.max(t.burning||0,dur+1);if(!isP(t))t.fireBy=1}});tiles((a,b)=>ignite(a,b,1));break;
 case 'frost':each(t=>{hurt(t,mag,c,'frost');if(!isP(t))t.slow=dur+3});tiles((a,b)=>freezeTile(a,b,dur*3+30));break;
 case 'shock':shockFrom(x,y,mag,c,at(x,y));each(t=>{if(!isP(t))t.stun=Math.max(t.stun||0,Math.min(3,dur))});break;
 case 'poison':each(t=>{if(!isP(t)){t.poison=Math.max(t.poison||0,dur+mag);t.poisonBy='p'}else poisonEnt(t,dur)});break;
 case 'drain':{let g=0;each(t=>{hurt(t,mag,c,'drain');g+=mag});p.hp=Math.min(p.mh,p.hp+g);break}
 case 'heal':{p.hp=Math.min(p.mh,p.hp+mag);if(area>0)RT.act.forEach(o=>{if(dist(o.x,o.y,p.x,p.y)<=area&&(o.ally||o.charm>0))o.hp=Math.min(o.mh,o.hp+mag)});break}
 case 'restore':{p.hunger=clamp(p.hunger+mag,0,100);p.thirst=clamp(p.thirst+mag,0,100);if(mag>=25){p.dz=[];msg('Every sickness leaves your body.','good')}break}
 case 'haste':p.fx.haste={v:Math.ceil(mag/6),t:dur+1};msg('Everything else slows down.','good');break;
 case 'might':p.fx.might={v:Math.ceil(mag/6),t:dur+1};recalc();msg('Strength floods your arms.','good');break;
 case 'invis':p.fx.invis={t:dur+1};msg('You fade from sight.','good');break;
 case 'aegis':p.fx.absorb={v:mag*2,t:dur+1};msg('A ward shimmers around you.','good');break;
 case 'timestop':p.fx.tstop={t:Math.max(1,dur)};msg('The world holds its breath.','story');story('Stopped time.',3);break;
 case 'sleep':each(t=>{if(isP(t))return;if(!t.aegis&&!SP[t.s].tags.undead&&!(SP[t.s].tags.mindless)&&(mag*3>=t.mh*.5||!mindResisted(t,mag/3))){t.sleep=dur*2+8;t.ko=1;G.stats.knockouts++;msg(SP[t.s].n+' collapses asleep.','good')}});break;
 case 'calm':each(t=>{if(isP(t)||t.aegis)return;if(mag*3>=t.mh*.5||!mindResisted(t,mag/3)){t.truce=G.turn+dur*3+15;t.alert=0;delete t.grudge;t.confused=0;msg(SP[t.s].n+' lowers its guard.','good')}});break;
 case 'fear':each(t=>{if(!isP(t)&&!t.aegis)t.fear=dur+4});break;
 case 'charm':each(t=>{if(isP(t)||t.aegis)return;if(t.id===G.kingId&&!t.aegis){msg('The king\'s eyes go flat.','story');endGame('puppet');return}if(mag*3>=t.mh*.6||!mindResisted(t,mag/3)){t.charm=dur*3+15;t.alert=0;t.grudge={};if(SP[t.s].tags.person)t.mindOld=t.fac;msg(SP[t.s].n+' now serves you.','good');G.stats.brainwash++}});break;
 case 'paralyze':each(t=>{if(!isP(t)&&!t.aegis)t.para=dur+1;});break;
 case 'confuse':each(t=>{if(!isP(t)&&!t.aegis)t.confused=dur+3});break;
 case 'quake':noise(x,y,20,'p');if(L.id==='world'&&regionAt(x,y)===RM&&seasonIdx()===3)avalanche(x,y);tiles((a,b)=>{const d=tdef(a,b);if(d.wall||d.door||d.k==='rock'||d.gate||d.k==='cavewall'){if(chance(mag/40+.25)){tset(a,b,'rubble');if(d.gate)msg('The gate buckles and falls.','warn')}}else if(d.chop){if(chance(.5))tset(a,b,'stump')}else if(d.p&&chance(.2)&&!d.water)tset(a,b,'pit');const o=at(a,b);if(o)hurt(o,Math.ceil(mag/3),c,'quake')});break;
 case 'inferno':tiles((a,b)=>{if(!ignite(a,b,1)&&tdef(a,b).p&&!tdef(a,b).water)L.fire[IX(a,b)]={t:dur+3,o:1}});story('Set the land ablaze with a word.',2);break;
 case 'deepfreeze':tiles((a,b)=>{freezeTile(a,b,dur*3+60);delete L.fire[IX(a,b)];const o=at(a,b);if(o&&!isP(o)){o.para=Math.min(6,dur);o.burning=0}});break;
 case 'rain':G.wx={k:'storm',t:dur*4+25};msg('Clouds pile up from nowhere.','wx');break;
 case 'growth':tiles((a,b)=>{const d=tdef(a,b),k=IX(a,b);if(L.crops[k]){L.crops[k].a=200}else if(['grass','ash','stump','sand','mud','scree'].includes(d.k)&&!at(a,b)&&chance(.55))tset(a,b,chance(.4)?'tree':'vines')});msg('The ground heaves with green.','good');break;
 case 'teleport':if(tdef(x,y).p&&!at(x,y)){p.x=x;p.y=y;msg('You step through the air.','good')}break;
 case 'raiseall':tiles((a,b)=>{raiseAt(a,b,p)});break;
 }}
function playerCast(s,x,y){const p=G.p;const d=SPELLS[s];if(p.mp<d.mp){msg('Not enough mana.','warn');return false}if(!d.self&&dist(p.x,p.y,x,y)>d.rng){msg('Out of range.','warn');return false}if(!d.self&&!los(p.x,p.y,x,y)&&s!=='blink'){msg('You have no line of sight.','warn');return false}if(s==='raise'&&!(L.items[IX(x,y)]||[]).some(i=>i.k==='corpse')){msg('There is no corpse there.','warn');return false}p.mp-=d.mp;const t=at(x,y);if(t&&!isP(t)&&SP[t.s].tags.person&&!hostile(t,p)&&(s==='firebolt'||s==='shock'||s==='frost'))crime('assault',t);castSpell(s,p,x,y);if(p.fx.invis)delete p.fx.invis;advance(100);return true}
function doThrow(it,x,y){const p=G.p,d=idef(it);if(dist(p.x,p.y,x,y)>7){msg('Too far to throw.','warn');return}const q=mk(it.k,1);if(it.sp)q.sp=it.sp;if(it.x)q.x=it.x;if(it.q>1)it.q--;else{if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;p.inv.splice(p.inv.indexOf(it),1)}RT.fxq.push({type:'shot',x:p.x,y:p.y,x2:x,y2:y});if(d.effect){msg('You throw '+d.n.toLowerCase()+'.','');const t=at(x,y);if(d.effect==='noise'&&t&&!isP(t)){hurt(t,2,p,'stone');msg('The stone cracks against '+SP[t.s].n+'.')}throwEffect(d.effect,x,y,p);if(d.effect!=='noise'&&t&&!isP(t)&&SP[t.s].tags.person&&!hostile(t,p))crime('assault',t);if(d.effect==='noise')addItem(L,x,y,mk('stone'))}else{addItem(L,x,y,q);msg(d.n+' lands nearby.','');noise(x,y,4)}advance(100)}

// ===== ITEMS =====
function useItem(it){const p=G.p,d=idef(it);if(d.k==='wpn'||d.k==='arm'){if(d.req){for(const s in d.req)if(p.st[s]<d.req[s]){msg('You need '+STATN[s]+' '+d.req[s]+' for that.','warn');return}}if(d.k==='wpn'){p.eq.w=p.eq.w===it?null:it;msg((p.eq.w?'You wield ':'You put away ')+d.n+'.');}else{p.eq.a=p.eq.a===it?null:it;msg((p.eq.a?'You wear ':'You take off ')+d.n+'.');if(p.eq.a&&d.disg)msg('Dressed as the '+FAC[d.disg].n+'. They will not look twice unless you get close or act strangely.','hint')}recalc();p.loaded=d.gun?p.loaded:p.loaded;advance(60);return}
 if(d.k==='food'||d.k==='drink'||d.k==='med'&&!d.spike){if(d.hun)p.hunger=clamp(p.hunger+d.hun,0,100);if(d.thi)p.thirst=clamp(p.thirst+d.thi,0,100);if(d.hp)p.hp=Math.min(p.mh,p.hp+d.hp);if(d.mp)p.mp=Math.min(p.mmp,p.mp+d.mp);if(d.warm)p.temp=Math.min(50,p.temp+d.warm);if(d.boost){p.fx.boost={k:d.boost,v:2,t:80};recalc();msg('You feel your '+STATN[d.boost]+' rise.','good')}if(d.cure){const before=p.dz.length;p.dz=[];p.fx.poison&&delete p.fx.poison;msg(before?'The sickness loosens and leaves you.':'It tastes bitter and clean.','good')}if(d.raw&&chance(p.herb?.08:.3))infect(p,'rot');if(d.dirty&&chance(.3))infect(p,'rot');if(d.risky&&chance(p.herb?.05:.2)){p.fx.poison={t:6};msg('That mushroom was a mistake.','bad')}msg('You '+(d.k==='drink'?'drink':d.k==='med'?'use':'eat')+' '+d.n.toLowerCase()+'.');const emp=d.empty;takeItem(it.k);if(emp)giveItem(mk(emp),true);advance(70);return}
 if(d.k==='scroll'){const s=it.sp;const sd=SPELLS[s];if(!sd){msg('The words are too faded.','warn');return}if(p.st.int<sd.int&&eff('int')<sd.int){msg('You need Intelligence '+sd.int+' to learn this.','warn');return}if(p.spells.includes(s)){msg('You already know this. You grind the scroll into dust.','hint');giveItem(mk('dust'),true)}else{p.spells.push(s);msg('You learn '+sd.n+'.','good');gainXP(10)}p.inv.splice(p.inv.indexOf(it),1);advance(100);return}
 if(d.k==='lore'||it.k==='letter'){if(d.lore){learnLore(d.lore)}else msg('A letter, sealed. Deliver it.','hint');return}
 if(it.k==='torch'){if(p.torch>0){msg('Your torch is already lit.','hint');return}takeItem('torch');p.torch=90;msg('You light a torch.','good');advance(40);return}
 if(d.k==='herb'&&p.herb&&it.k==='bloodmoss'){p.hp=Math.min(p.mh,p.hp+6);takeItem(it.k);msg('You chew the moss. It helps a little.','good');advance(70);return}
 msg('You cannot use that directly. Try throwing it, or crafting with it.','hint')}
function dropItem(it){const p=G.p;const q={k:it.k,q:it.q||1};if(it.sp)q.sp=it.sp;if(it.x)q.x=it.x;if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;p.inv.splice(p.inv.indexOf(it),1);addItem(L,p.x,p.y,q);msg('You drop '+iname(q)+'.');const d=idef(q);if(d.meat&&!p.sneak)msg('The smell of meat drifts on the wind.','hint');advance(40)}
function foodList(){return G.p.inv.filter(i=>idef(i).k==='food'||idef(i).k==='bait')}
function pickupAll(x,y){const k=IX(x,y),its=L.items[k];if(!its)return;for(const it of its.slice()){if(it.k==='corpse')continue;if(giveItem(it)){its.splice(its.indexOf(it),1)}}if(!its.length)delete L.items[k];advance(50)}
function butcher(x,y){const k=IX(x,y),its=L.items[k];if(!its)return;const c=its.find(i=>i.k==='corpse');if(!c)return;its.splice(its.indexOf(c),1);if(!its.length)delete L.items[k];const sp=SP[c.sp];let got=0;if(sp&&!sp.tags.person){Object.entries(sp.loot||{}).forEach(([m,q])=>{addItem(L,x,y,mk(m,ri(1,q)));got=1});addItem(L,x,y,mk('rawmeat',1))}addItem(L,x,y,mk('bone',1));if(c.dz==='zombie'&&chance(.6)){addItem(L,x,y,mk('bile',1));msg('You drain a vial of grey bile from the veins. Handle with care.','warn')}if(c.dz&&chance(.3))infect(G.p,c.dz==='cough'?'cough':'rot');msg('You butcher the corpse.','');if(sp&&sp.tags.person){crime('desecration',{fac:'free'});msg('It is grim work.','warn')}advance(200)}
function sleepRest(bed){const p=G.p;let n=bed?40:15;msg(bed?'You lie down to sleep.':'You rest.','hint');for(let i=0;i<n&&!G.over;i++){const danger=RT.act.some(c=>hostile(c,p)&&dist(c.x,c.y,p.x,p.y)<=7&&c.sleep<=0&&(c.alert>=1)&&visible(c.x,c.y));if(danger&&i>0){msg('Something wakes you!','bad');break}advance(100);if(RT.hit){RT.hit=0;msg('You wake up hurt!','bad');break}if(i%3===0)p.hp=Math.min(p.mh,p.hp+(bed?2:1));p.mp=Math.min(p.mmp,p.mp+(bed?1:0))}if(bed)msg('You wake.','')}

// ===== CRAFT =====
function craftAvail(r){if(r.near==='cook'&&!nearHeatT())return false;if(r.near==='forge'&&!nearForge())return false;return Object.entries(r.need).every(([k,q])=>count(k)>=q)}
function nearHeatT(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(tdef(p.x+dx,p.y+dy).cook||L.fire[IX(p.x+dx,p.y+dy)])return true}return false}
function nearForge(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(tdef(p.x+dx,p.y+dy).forge)return true;return false}
function nearSpellforge(){const p=G.p;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(tdef(p.x+dx,p.y+dy).arcane)return true;return false}
function doCraft(r){if(!craftAvail(r))return;Object.entries(r.need).forEach(([k,q])=>takeItem(k,q));giveItem(mk(r.out,r.q||1),true);msg('You make '+iname(mk(r.out,r.q||1))+'.','good');G.stats.crafted++;gainXP(1);advance(r.near?150:100)}
function forgeCost(b,m,e){const B=FBASE[b],M=FMAT[m],E=FENCH[e];const q=Math.max(1,B.cost);return{mat:M.it,matq:q,wood:B.kind==='wpn'?1:0,dust:E.dust,}}
function canForge(b,m,e){const c=forgeCost(b,m,e);return count(c.mat)>=c.matq&&count('wood')>=c.wood&&count('dust')>=c.dust}
function doForge(b,m,e){if(!nearForge()){msg('You need to stand beside a forge.','warn');return}if(!canForge(b,m,e)){msg('You lack the materials.','warn');return}const B=FBASE[b],M=FMAT[m],E=FENCH[e],c=forgeCost(b,m,e);takeItem(c.mat,c.matq);if(c.wood)takeItem('wood',c.wood);if(c.dust)takeItem('dust',c.dust);
 const skill=eff('str')+(G.p.forge||0)*2;const qual=Math.min(3,Math.floor(skill/5)+(chance(.3)?1:0));const qn=['Crude ','','Fine ','Masterwork '][qual];const x={k:B.kind,g:B.kind==='arm'?'[':(B.rng?'}':'/'),c:M.arcane?'#9cf':'#cde',st:B.st,req:B.req?Object.assign({},B.req):undefined,v:Math.round((30+B.cost*10)*M.mult),noisy:B.noisy,quiet:B.quiet,mercy:B.mercy,manaP:B.manaP?Math.round(B.manaP*M.mult):undefined,warm:B.warm,chop:B.chop,gun:B.gun,norld:B.norld,rng:B.rng};if(M.light&&x.req)Object.keys(x.req).forEach(k=>x.req[k]=Math.max(1,x.req[k]-1));if(B.kind==='wpn')x.d=Math.round(B.d*M.mult)+qual-1;else x.ar=Math.round(B.ar*M.mult)+Math.max(0,qual-1);if(e!=='none'){x.ench=e;if(e==='mercy')x.mercy=1;if(e==='silence')x.quiet=1}x.n=qn+M.n+' '+B.n+(e!=='none'?' of '+E.n:'');Object.keys(x).forEach(k=>x[k]===undefined&&delete x[k]);const it={k:'forged',q:1,x};G.p.inv.push(it);msg('You forge '+x.n+'.','good');story('Forged '+x.n+'.',1);G.stats.crafted++;gainXP(6);noise(G.p.x,G.p.y,6,'p');advance(300);return it}
function makeSpell(name,fx,target){const p=G.p;const sp={id:'c'+(++G.cid),name:name||'Unnamed Working',fx,target};const c=spellCost(sp);const dust=Math.max(1,Math.ceil(c/18));if(!nearSpellforge()){msg('You need a spellforge.','warn');return null}if(count('dust')<dust){msg('This working needs '+dust+' arcane dust.','warn');return null}if(p.st.int+p.lvl<Math.min(12,1+Math.ceil(c/12))){msg('This is beyond your Intelligence. Lower the magnitude, area, or duration.','warn');return null}takeItem('dust',dust);p.custom.push(sp);msg('You inscribe '+sp.name+'. It costs '+c+' mana.','good');story('Invented the spell '+sp.name+'.',2);G.stats.spellsMade++;gainXP(12);advance(300);return sp}

// ===== WORLD VERBS =====
function digTile(x,y){const d=tdef(x,y);if(d.k==='rock'||d.mine){const w=idef(G.p.eq.w);if(!(w.minep||hasItem('pick'))){msg('You need a pickaxe.','warn');return}noise(x,y,8,'p');if(d.ore===2)addItem(L,G.p.x,G.p.y,mk('starore',ri(1,2)));else if(d.ore)addItem(L,G.p.x,G.p.y,mk('ironore',ri(1,3)));else addItem(L,G.p.x,G.p.y,mk('stone',ri(1,3)));tset(x,y,L.dark?'cavefloor':'rubble');msg('The rock comes apart.','');advance(300)}}
function chopTile(x,y){const d=tdef(x,y);noise(x,y,8,'p');addItem(L,G.p.x,G.p.y,mk('wood',ri(2,3)));tset(x,y,'stump');msg('The tree comes down.','');if(d.hive)angerBees(x,y);advance(250)}
function angerBees(x,y){for(let i=0;i<3;i++){const c=spawn('bees',clamp(x+ri(-1,1),1,L.w-2),clamp(y+ri(-1,1),1,L.h-2),{grudge:{p:1},alert:2});RT.occ.set(IX(c.x,c.y),c)}msg('The hive erupts!','bad')}
function forageTile(x,y){const d=tdef(x,y);const p=G.p;const R0=regionAt(x,y),se=seasonIdx();if(d.k==='bush'){giveItem(mk('berries',ri(2,se===2?5:3)),false);if(chance(.15))giveItem(mk('seed'+pick(['wheat','turnip','gourd']),1));tset(x,y,'bushbare')}else if(d.k==='mushrooms'){if(chance(.25))giveItem(mk('madcap'));else giveItem(mk('mushroom',ri(1,3)));tset(x,y,L.dark?'cavefloor':'grass')}else if(d.k==='herb'){const pool=R0===RJ?['bloodmoss','dreamroot','ashcap','madcap']:R0===RD?['sunleaf','ashcap']:R0===RM?['sunleaf','bloodmoss','dreamroot']:['bloodmoss','sunleaf','dreamroot'];giveItem(mk(pick(pool),p.herb?2:1));tset(x,y,'grass')}else if(d.k==='cactus'){hurt(p,1,null,'cactus');giveItem(mk('cactusfruit',ri(1,2)));tset(x,y,'sand')}advance(120)}
function harvestCrop(x,y){const k=IX(x,y),c=L.crops[k];if(!c)return;const def=CROPS[c.c];if(c.a<def.grow){msg('Not ripe yet.','hint');return}giveItem(mk(def.item,def.q+(seasonIdx()===2?1:0)));if(chance(.6))giveItem(mk('seed'+c.c),true);delete L.crops[k];gainXP(2);if(!c.o&&L===G.levels.world){}advance(120)}
function plant(x,y,it){const k=IX(x,y);if(seasonIdx()===3){msg('The ground is frozen. Wait for spring.','warn');return}takeItem(it.k);L.crops[k]={c:idef(it).crop,a:0,o:1};msg('You plant '+CROPS[idef(it).crop].n+'.','good');advance(100)}
function waterCrop(x,y){const k=IX(x,y),c=L.crops[k];if(c&&takeItem('water')){c.w=G.turn+60;giveItem(mk('flask'),true);msg('You water the crop.','');advance(100)}}
function douse(x,y){if(!takeItem('water'))return;giveItem(mk('flask'),true);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)delete L.fire[IX(x+dx,y+dy)];addGas(x,y,'steam',3);const e=at(x,y);if(e&&!isP(e)){e.burning=0;e.wet=8}msg('You douse the flames.','good');advance(90)}
function lockpickTile(x,y){const d=tdef(x,y);if(!hasItem('lockpick')){msg('You have no lockpicks.','warn');return}const pct=clamp(25+eff('sth')*5+eff('agi')*3,10,95);if(chance(pct/100)){tset(x,y,d.gate?'gateopen':'dooropen');msg('The lock clicks open.','good');gainXP(4);if(d.gate)story('Picked the lock of the '+d.n+'.',2)}else{msg('The pick snaps in the lock.','warn');takeItem('lockpick');noise(x,y,6,'p')}advance(150)}
function useKey(x,y){tset(x,y,'gateopen');msg('The key turns.','good');advance(100)}
function buildAt(k,x,y){const B=BUILD[k];if(dist(G.p.x,G.p.y,x,y)>1&&!(k==='soil')){msg('Stand next to the spot.','warn');return}const d=tdef(x,y);if(at(x,y)&&!isP(at(x,y))){msg('Something is standing there.','warn');return}if(k==='bridge'){if(!(d.water)){msg('Bridges go on water.','warn');return}}else if(!(d.p&&!d.water&&!d.link&&d.k!=='altar'&&d.k!=='throne')){if(d.k==='soil'){}else{msg('You cannot build there.','warn');return}}if(k==='soil'&&isP(at(x,y)||{})&&false)return;if(B.tool&&!hasItem(B.tool)){msg('You need a '+ITEMS[B.tool].n.toLowerCase()+'.','warn');return}for(const[m,q]of Object.entries(B.need))if(count(m)<q){msg('You need '+q+' '+ITEMS[m].n.toLowerCase()+'.','warn');return}Object.entries(B.need).forEach(([m,q])=>takeItem(m,q));tset(x,y,k);if(TDEF[k].store)L.stores[IX(x,y)]=[];msg('You build '+BUILD[k].n.toLowerCase()+'.','good');gainXP(1);noise(x,y,5,'p');advance(150)}
function takeStore(x,y,it){const k=IX(x,y),st=L.stores[k];st.splice(st.indexOf(it),1);giveItem(it);advance(50)}
function putStore(x,y,it){const k=IX(x,y);const p=G.p;p.inv.splice(p.inv.indexOf(it),1);if(p.eq.w===it)p.eq.w=null;if(p.eq.a===it)p.eq.a=null;(L.stores[k]=L.stores[k]||[]).push(it);msg('Stored.','');advance(40)}
function gatherSmoke(x,y){const near=(L.gas[IX(x,y)]||{}).k==='smoke';const w=DIRS.some(([a,b])=>(L.gas[IX(x+a,y+b)]||{}).k==='smoke');if(near||w||seasonIdx()===3){giveItem(mk('honey',ri(1,3)));giveItem(mk('wax',1));msg(seasonIdx()===3?'The cold has the bees torpid. You take the comb.':'The smoke keeps the bees docile. You take the comb.','good');tset(x,y,'tree')}else{angerBees(x,y);giveItem(mk('honey',1))}advance(150)}
function drinkTile(x,y){const d=tdef(x,y);const p=G.p;const reg=regionAt(x,y);p.thirst=clamp(p.thirst+40,0,100);msg('You drink deep.','good');if((d.k==='bog'||reg===RJ&&d.water)&&chance(.2))infect(p,'marsh');else if(d.water&&d.k!=='oasis'&&d.k!=='spring'&&chance(.05))infect(p,'rot');advance(70)}
function fillFlask(x,y){const n=count('flask');if(!n)return;takeItem('flask',n);const reg=regionAt(x,y);giveItem(mk(reg===RJ&&tdef(x,y).water?'dirtywater':'water',n),true);msg('You fill '+n+' flask'+(n>1?'s':'')+'.','good');advance(70)}
function goLink(x,y){const p=G.p;const k=IX(x,y);const d=tdef(x,y);if(d.k==='down'){const lk=L.links[k];const lv=ensureLevel(lk);lv.backTo=lv.backTo||{lv:L.id,x,y};p.lv=lv.id;L=lv;const e=lv.exitAt||{x:1,y:1};p.x=e.x;p.y=e.y;rebuild();computeFOV();msg(lk.to==='tomb'?'You descend into the Tomb of Sephet. The air tastes of old salt.':'You climb down into darkness. Light a torch.','story');if(lk.to==='tomb'&&!G.flags.tombOpen){G.flags.tombOpen=G.turn}advance(100)}else if(d.k==='up'){const back=L.backTo;if(!back)return;const lv=G.levels[back.lv];p.lv=back.lv;L=lv;p.x=back.x;p.y=back.y;rebuild();computeFOV();msg('You climb back to the surface.','');advance(100)}}
function burnGranary(x,y){ignite(x,y,1);G.moraleH=Math.max(0,G.moraleH-25);msg('The Horde\'s winter grain goes up. Morale will crack.','story');story('Burned the Horde granary.',2);advance(100)}

// ===== TALK =====
function pChance(c,base){const p=G.p;let v=base+eff('int')*4+p.speak;const f=c.fac;if(REPF.includes(f))v+=Math.round(G.rep[f]/5);if(c.hp<c.mh*.5)v+=10;if(c.annoy)v-=c.annoy*12;if(disguised(c))v+=20;const se=seasonIdx();if(se===2)v+=5;if(se===3&&c.hunger>60)v+=8;if(c.dz==='mania')v-=40;if(SP[c.s].tags.dim)v+=15;if(p.dz.some(z=>z.k==='mania'))v-=25;return clamp(Math.round(v),5,95)}
function roll(pct){return R()*100<pct}
function repGain(f,n){if(REPF.includes(f))G.rep[f]=clamp(G.rep[f]+n,-100,100)}
function priceMul(k){const d=ITEMS[k];const se=seasonIdx();let m=1;if(d.k==='food'){m=[1.1,1,.65,2][se];if(G.flags.festival)m*=.7}if(k==='furcoat'||k==='pelt')m*=se===3?1.6:se===1?.7:1;if(k==='shroud'||k==='water')m*=se===1?1.6:1;if(k==='tonic'&&(G.flags.grey||G.flags.mania))m*=1.8;return m}
function genStock(c){const s=c.s;const list={merchant:['bread','cooked','water','flask','torch','rope','shot','lockpick','seedwheat','seedturnip','seedgourd','pelt','oilflask','furcoat','shroud','shovel'],smith:['iron','steel','pick','axe','spear','chain','pistol','musket','shot','club','stone'],healer:['salve','tonic','bloodmoss','sunleaf','dreamroot','manapot','sleepdraught'],hermit:['mushroom','dreamroot','rope','diary_hint','salve'],shaman:['dreamroot','ashcap','bloodmoss','madcap','tonic','poisonvial','sleepdraught','silk'],nomad:['water','cactusfruit','jerky','shroud','shot','musket','oilflask','sunleaf','ring'],goblin:['stone','bone','fang','firebomb','smokebomb','powder','lockpick','madvial','ring'],witch:['dust','manapot','scroll:shock','scroll:fear','scroll:charm','scroll:gust','scroll:blink','scroll:sleep','scroll:firebolt','scroll:brainwash','scroll:raise','sleepdraught']}[s]||['bread','water'];c.stock=list.filter(k=>k.startsWith('scroll')||ITEMS[k]).map(k=>{if(k.startsWith('scroll:'))return{k:'scroll',sp:k.split(':')[1],q:1};return{k,q:ri(1,4)}})}
function tradeSheet(c){if(!c.stock)genStock(c);const opts=[];const rm=1-Math.max(-30,Math.min(30,(G.rep[c.fac]||0)))/120-eff('int')*.012-(G.p.speak?.1:0);c.stock.forEach(st=>{const name=iname(st);const base=st.k==='scroll'?60:(ITEMS[st.k].v||1);const pr=Math.max(1,Math.round(base*priceMul(st.k)*rm));opts.push({label:'Buy '+name,sub:pr+' coins',disabled:G.p.coins<pr,fn:()=>{G.p.coins-=pr;const q=mk(st.k,1);if(st.sp)q.sp=st.sp;giveItem(q);st.q--;if(st.q<=0)c.stock.splice(c.stock.indexOf(st),1);return tradeSheet(c)}})});G.p.inv.filter(i=>i!==G.p.eq.w&&i!==G.p.eq.a&&idef(i).v>0&&idef(i).k!=='quest'&&idef(i).k!=='lore').forEach(it=>{const pr=Math.max(1,Math.round(idef(it).v*priceMul(it.k)*.45));opts.push({label:'Sell '+iname(it),sub:pr+' coins each',fn:()=>{G.p.coins+=pr;if(it.q>1)it.q--;else G.p.inv.splice(G.p.inv.indexOf(it),1);return tradeSheet(c)}})});opts.push({label:'Done',fn:()=>talkSheet(c)});return{title:'Trade with '+SP[c.s].n,text:seasonIdx()===3?'Winter prices. Food is dear.':G.flags.festival?'Festival prices.':seasonIdx()===2?'Harvest prices. Food is cheap.':'You have '+G.p.coins+' coins.',options:opts}}
const RUMORS={free:['Horde raiders come south every summer. Keep your powder dry.','Fort Hollow\'s lord Rusk has a shard of old jade. He sleeps like the dead at night.','The river freezes in winter. Thin ice over the deep channel, mind.','Wolves take the outlying farms in hard winters. Bring food, not swords.'],hunter:['Ixa sleeps when the rains stop. The dry cold months are the time to walk past her.','Smoke drives the brood out. Fire takes the whole temple.','Bog gas burns. Do not bring a torch into the low swamp.','Do not drink the jungle water unless you want fever.'],nomad:['The dead of Sephet\'s tomb are thirsty. A thirsty thing can be reasoned with.','The queen likes riddles. The old songs say so.','Walk at night in summer or wear a shroud, or the sun will have you.','The worm follows footfalls. Walk softly on the sand.'],horde:['The King does not eat anymore. He just talks to the amulet.','Winter rations are half what they were. Half the camp wants out.','The gate key stays on the captain.','There is an old grate on the east wall. Nobody admits to using it.'],bandit:['Rusk would sell his own mother for the right price.','We don\'t fight the Horde. Nobody fights the Horde.'],goblin:['Goblin knows things! Goblin knows bombs! Buy something!'],troll:['Troll like riddle. Troll like coin. Troll not like fire.']};
function talkSheet(c){const d=SP[c.s],p=G.p,o=[];const host=hostile(c,p);const mania=c.dz==='mania';let text=d.n+(c.sleep>0?' is asleep.':host?' eyes you with open hostility.':' waits for you to speak.');
 if(c.sleep>0)return{title:d.n,text,options:[{label:'Leave',fn:()=>null}]};if(mania)text='Their eyes are red and wet. They laugh at nothing.';if(c.dz==='zombie'&&!d.tags.undead)text+=' Black veins climb their neck.';
 if(c.ally||c.charm>0){o.push({label:c.stay?'Follow me':'Stay here',fn:()=>{c.stay=!c.stay;msg(c.stay?d.n+' will wait here.':d.n+' falls in behind you.');return null}});if(c.ally)o.push({label:'You are free to go',fn:()=>{c.ally=0;c.charm=0;msg(d.n+' leaves.');return null}})}
 const addPersuade=()=>{if(host){const pc=pChance(c,10);o.push({label:'Persuade them to stand down',sub:pc+'%',fn:()=>{G.stats.talks++;if(roll(pc)){c.truce=G.turn+200;c.alert=0;delete c.grudge;msg(d.n+' lowers their weapon.','good');gainXP(5);bark(c,'...Fine. Walk on.');return null}c.annoy=(c.annoy||0)+1;msg(d.n+' is not impressed.','warn');c.alert=2;advance(100);return null}})}
  if(d.tags.person&&!c.ally&&!d.tags.unique){const pc=pChance(c,-5);o.push({label:'Ask them to join you',sub:pc+'%',fn:()=>{G.stats.talks++;if(roll(pc)){c.ally=1;c.alert=0;delete c.grudge;msg(d.n+' falls in beside you.','good');gainXP(6);story(d.n+' joined you by choice.',1)}else{c.annoy=(c.annoy||0)+1;msg(d.n+' refuses.','warn')}advance(100);return null}})}
  const kin=RT.act.filter(q=>q!==c&&q.fac===c.fac&&dist(q.x,q.y,c.x,c.y)<=8);if(d.tags.person&&kin.length&&!d.tags.unique){const pc=pChance(c,5);const tn=kin[0];o.push({label:'Lie: "'+SP[tn.s].n+' plans to kill you."',sub:pc+'%',fn:()=>{G.stats.lies++;if(roll(pc)){(c.grudge=c.grudge||{})[tn.id]=1;msg(d.n+' turns on '+SP[tn.s].n+' with a snarl!','good');story('Talked '+d.n+' into attacking its own side.',3);gainXP(6)}else{c.annoy=(c.annoy||0)+1;msg(d.n+' laughs in your face.','warn');if(host)c.alert=2}advance(100);return null}})}
  if(d.tags.person&&!d.tags.unique){const pc=pChance(c,10);o.push({label:'Lie: "They need you elsewhere. Go."',sub:pc+'%',fn:()=>{G.stats.lies++;if(roll(pc)){const sx=clamp(c.x+ri(-14,14),2,L.w-3),sy=clamp(c.y+ri(4,14),2,L.h-3);c.job='patrol';c.home={x:sx,y:sy};c.goal={x:sx,y:sy};c.truce=G.turn+40;c.alert=0;msg(d.n+' nods and hurries off.','good');gainXP(4)}else{c.annoy=(c.annoy||0)+1;msg(d.n+' does not buy it.','warn')}advance(100);return null}})}
  if(d.tags.person&&!d.tags.unique){const pc=clamp(Math.round(20+eff('str')*5+(p.threat||0)+p.lvl*3-c.hp*.8+(host?0:-10)),5,95);o.push({label:'Threaten them',sub:pc+'%',fn:()=>{G.stats.talks++;if(roll(pc)){c.fear=25;if(c.coins){p.coins+=c.coins;msg(d.n+' throws you '+c.coins+' coins and backs away.','good');c.coins=0}else msg(d.n+' backs away, shaking.','good');gainXP(3);repGain(c.fac,-3)}else{c.alert=2;(c.grudge=c.grudge||{}).p=1;msg(d.n+' draws steel!','warn')}advance(100);return null}})}
  if(d.tags.greedy||d.tags.person&&host){const cost=Math.max(10,(d.tags.greedy?10:25)+(c.mh>>2));if(p.coins>=cost&&!d.tags.unique)o.push({label:'Bribe them',sub:cost+' coins',fn:()=>{p.coins-=cost;c.coins=(c.coins||0)+cost;c.truce=G.turn+250;c.alert=0;delete c.grudge;msg(d.n+' pockets the coins and looks the other way.','good');gainXP(3);return null}})}};
 if(c.witness&&!host){const cost=25;if(p.coins>=cost)o.push({label:'Pay them to keep quiet',sub:cost+' coins',fn:()=>{p.coins-=cost;delete c.witness;msg(d.n+' saw nothing.','good');return null}})}
 if(!host||c.truce>G.turn){const f=c.fac;o.push({label:'Ask what they know',fn:()=>{const pool=RUMORS[f]||['...'];const sites=G.sites.filter(q=>!q.known&&!q.cave);if(!c.told){gainXP(1);c.told=1}let r=pick(pool);if(sites.length&&chance(.45)){const s=pick(sites);s.known=1;r='There\'s '+s.name+' to the '+compass(s.x-p.x,s.y-p.y)+'. Marked on your map.';}msg(d.n+': "'+r+'"','say');if(c.s==='shaman'&&!p.lore.includes('shaman')&&G.rep.hunter>=0&&false)learnLore('shaman');return talkSheet(c)}})
  if(d.tags.trader)o.push({label:'Trade',fn:()=>tradeSheet(c)});if(d.tags.healer&&p.dz.length){const cost=c.s==='shaman'?15:25;if(p.coins>=cost)o.push({label:'Ask to be cured',sub:cost+' coins',fn:()=>{p.coins-=cost;p.dz=[];msg('They clean the sickness from your blood.','good');return talkSheet(c)}})}
  questOptions(c,o)}
 // feed anyone
 const fd=foodList()[0];if(fd&&(d.tags.person)&&!(c.ally)){const hungry=c.hunger>55||seasonIdx()===3;o.push({label:'Offer them '+idef(fd).n.toLowerCase(),sub:hungry?'They look starving':'',fn:()=>feedC(c,fd)})}
 if(hasItem('tonic')&&c.dz&&!d.tags.undead)o.push({label:'Give them a cleansing tonic',fn:()=>{takeItem('tonic');delete c.dz;delete c.dzT;msg(d.n+' shudders, and their eyes clear.','good');repGain(c.fac,8);G.stats.cured++;gainXP(8);story('Cured '+d.n+' of plague.',2);advance(100);return null}});
 specialTalk(c,o);if(!d.tags.unique||host)addPersuade();
 o.push({label:'Leave',fn:()=>null});return{title:d.n,text,options:o}}
function compass(dx,dy){const ns=dy<-3?'north':dy>3?'south':'';const ew=dx<-3?'west':dx>3?'east':'';return (ns+ew)||'nearby'}
function feedC(c,fd){const d=SP[c.s];const dd=idef(fd);if(dd.bait){if(fd.q>1)fd.q--;else G.p.inv.splice(G.p.inv.indexOf(fd),1);baitEffect(c,dd.bait);advance(100);return null}takeItem(fd.k);const hungry=c.hunger>55||seasonIdx()===3;c.hunger=0;msg(d.n+(hungry?' tears into the food, close to tears.':' accepts the food.'),'good');repGain(c.fac,hungry?6:2);gainXP(hungry?5:1);if(d.tags.animal||!REPF.includes(c.fac)){c.fed=G.turn+150;c.feeds=(c.feeds||0)+1;if(c.feeds>=2&&(d.tags.animal)&&!d.tags.swarm){c.tame=1;c.ally=1;msg(d.n+' follows you now. You have a companion.','good');story('Tamed '+d.n+' with food.',2)}}if(c.job==='deserter'){G.moraleH=Math.max(0,G.moraleH-8);msg('Word of your food will reach the camps.','hint');if(chance(.6)){const b=mk('banner');msg(d.n+' presses a torn Horde banner on you: "Take it. I am done with him."','good');giveItem(b)}c.job='patrol';c.truce=G.turn+500;c.home={x:c.x,y:c.y+20}}if(c.fac==='horde'&&seasonIdx()===3){G.moraleH=Math.max(0,G.moraleH-5);c.truce=G.turn+200;c.alert=0;delete c.grudge}advance(100);return null}
function specialTalk(c,o){const d=SP[c.s],p=G.p;
 if(c.s==='rusk'&&c.inv.some(i=>i.k==='piece_grass')){o.unshift({label:'Buy the shard',sub:'60 coins',disabled:p.coins<60,fn:()=>{p.coins-=60;c.coins=(c.coins||0)+60;c.inv=c.inv.filter(i=>i.k!=='piece_grass');giveItem(mk('piece_grass'));msg('Rusk: "Pleasure. Don\'t tell the king where you got it."','say');c.truce=G.turn+800;delete c.grudge;gainXP(10);story('Bought the shard from Rusk without a fight.',2);return null}});const pc=pChance(c,5);o.unshift({label:'"Vorgath will kill you for that shard. Give it to me."',sub:pc+'%',fn:()=>{G.stats.talks++;if(roll(pc)){c.inv=c.inv.filter(i=>i.k!=='piece_grass');giveItem(mk('piece_grass'));msg('Rusk goes quiet, then throws it at your chest. "Then YOU can die for it."','say');c.truce=G.turn+800;delete c.grudge;gainXP(12);story('Talked Rusk out of the shard.',3)}else{c.annoy=(c.annoy||0)+1;msg('Rusk: "Nobody threatens me in my own house."','say');advance(100)}return null}});o.unshift({label:'Play dice for the shard',sub:'stake 20 coins, Stealth lets you cheat',disabled:p.coins<20,fn:()=>{p.coins-=20;const pc2=clamp(35+eff('sth')*5,5,92);if(roll(pc2)){c.inv=c.inv.filter(i=>i.k!=='piece_grass');giveItem(mk('piece_grass'));msg('Your dice land true. Rusk stares, then roars with laughter. The shard is yours.','good');gainXP(10);c.truce=G.turn+800;story('Won the shard from Rusk at dice.',3)}else{msg('Rusk rakes in your coins. "Again?"','warn');advance(50)}return talkSheet(c)}});const fq=foodList().reduce((a,i)=>a+(i.q||1),0);if(seasonIdx()===3)o.unshift({label:'Feed his starving band (6 food)',sub:'Winter only. You have '+fq,disabled:fq<6,fn:()=>{for(let i=0;i<6;i++){const f=foodList()[0];if(f)takeItem(f.k)}c.inv=c.inv.filter(i=>i.k!=='piece_grass');giveItem(mk('piece_grass'));repGain('bandit',30);msg('Rusk: "We\'d have eaten each other by spring. Take your rock."','say');story('Traded a winter\'s food for the shard.',3);gainXP(14);return null}})}
 if(c.s==='ixa'){const m=count('rawmeat')+count('cooked');o.unshift({label:'Offer the brood 3 meat',sub:'You have '+m,disabled:m<3,fn:()=>{let n=3;['rawmeat','cooked'].forEach(k=>{while(n>0&&takeItem(k))n--});c.truce=G.turn+900;c.fed=G.turn+900;delete c.grudge;c.alert=0;msg('Ixa: "Small warm thing. You may take the shiny stone. Leave quietly."','say');RT.act.filter(q=>q.fac==='spider').forEach(q=>{q.truce=G.turn+900;q.fed=G.turn+900;delete q.grudge;q.alert=0});G.flags.ixaFed=1;story('Fed Ixa and walked out with her blessing.',3);gainXP(12);advance(100);return null}});const pc=pChance(c,-5);o.unshift({label:'"Vorgath will burn your nest."',sub:pc+'%',fn:()=>{if(roll(pc)){c.truce=G.turn+500;delete c.grudge;msg('Ixa: "Then take it, and go kill him."','say');gainXP(10)}else{msg('Ixa clicks her mandibles. It might be laughter.','warn');c.annoy=(c.annoy||0)+1;advance(100)}return null}})}
 if(c.s==='sephet'&&!G.flags.sephetDone){o.unshift({label:'Answer her riddle',fn:()=>riddle(c,()=>{G.flags.sephetDone=1;c.truce=G.turn+9999;msg('Sephet: "A mind, at last. Take the shard. Tell the living I was clever."','say');story('Out-riddled the dead queen.',3);RT.act.filter(q=>q.fac==='undead').forEach(q=>{q.truce=G.turn+9999;delete q.grudge;q.alert=0});gainXP(20)})});const w=count('water');o.unshift({label:'Pour out 3 flasks for the thirsting dead',sub:'You have '+w,disabled:w<3,fn:()=>{takeItem('water',3);giveItem(mk('flask',3),true);G.flags.sephetDone=1;RT.act.filter(q=>q.fac==='undead').forEach(q=>{if(q.s==='thirsty'||q.s==='skeleton'){q.life=2}else{q.truce=G.turn+9999}delete q.grudge;q.alert=0});msg('The water sinks into the stones. One by one, the dead lie down.','story');story('Gave the dead water, and they finally rested.',4);gainXP(25);return null}});if(p.spells.includes('raise'))o.unshift({label:'Command the dead as a necromancer',sub:pChance(c,15)+'%',fn:()=>{if(roll(pChance(c,15))){G.flags.sephetDone=1;c.truce=G.turn+9999;delete c.grudge;msg('Sephet bows, hating you. The tomb is yours.','story');gainXP(20)}else{msg('Sephet: "You dare!"','say');c.alert=2;advance(100)}return null}})}
 if(c.s==='troll'&&!c.passed){o.unshift({label:'Pay the toll',sub:'25 coins',disabled:p.coins<25,fn:()=>{p.coins-=25;c.passed=1;c.truce=G.turn+9999;delete c.grudge;msg('Troll: "Good coin. Go."','say');return null}});o.unshift({label:'Riddle the troll',fn:()=>riddle(c,()=>{c.passed=1;c.truce=G.turn+9999;delete c.grudge;msg('Troll: "Hrrm. Clever. Go by."','say');gainXP(10)})})}
 if(c.s==='hermit'&&!p.lore.includes('hermit'))o.unshift({label:'Ask about the king',fn:()=>{learnLore('hermit');return talkSheet(c)}});
 if(c.s==='nelder'&&!p.lore.includes('nomad')){const w=count('water');o.unshift({label:'Share water, then ask about the king',sub:'1 flask',disabled:w<1,fn:()=>{takeItem('water');giveItem(mk('flask'),true);repGain('nomad',8);learnLore('nomad');return talkSheet(c)}})}
 if(c.s==='hshaman'&&!p.lore.includes('shaman')){const pc=pChance(c,10);o.unshift({label:'Ask what the Aegis really is',sub:pc+'%',fn:()=>{if(roll(pc))learnLore('shaman');else{msg('The shaman spits.','warn');c.annoy=(c.annoy||0)+1;advance(100)}return talkSheet(c)}})}
 if(c.s==='witch'){o.unshift({label:'Ask to use the spellforge',fn:()=>{msg('Witch: "Stand beside it. Bring arcane dust. Try not to set the roof alight."','say');return null}});if(!p.lore.includes('witch')&&false){}}
 if(c.s==='smith')o.unshift({label:'Ask about forging',fn:()=>{msg('Smith: "Stand at the forge. Bars, wood, and dust if you want it enchanted. Star-iron ore is deep in the caves."','say');return talkSheet(c)}});
 if(c.fac==='horde'&&c.job==='gate'&&tileGate()){const pc=pChance(c,5)+(disguised(c)?15:0)+(hasItem('banner')?10:0);o.unshift({label:'Lie: "Courier for the King. Open up."',sub:pc+'%',fn:()=>{G.stats.lies++;if(roll(pc)){openKeepGate();c.truce=G.turn+300;delete c.grudge;msg(d.n+' grunts and hauls the gate open.','good');story('Bluffed through the Keep\'s gate.',3);gainXP(10)}else{c.annoy=(c.annoy||0)+1;c.alert=2;(c.grudge=c.grudge||{}).p=1;c.sawThrough=1;msg(d.n+': "No courier smells like you."','say');advance(100)}return null}})}
 if(c.fac==='horde'&&d.tags.leader&&!c.swayed){const pc=pChance(c,seasonIdx()===3?5:-5);o.unshift({label:'"He is mad, and you know it. Stand aside when it comes."',sub:pc+'%',fn:()=>{G.stats.talks++;if(roll(pc)){c.swayed=1;c.truce=G.turn+800;delete c.grudge;G.moraleH=Math.max(0,G.moraleH-15);msg(d.n+' does not answer, and does not stop you either.','good');story('Turned a Horde captain against the king.',3);gainXP(12)}else{c.alert=2;(c.grudge=c.grudge||{}).p=1;c.annoy=(c.annoy||0)+1;advance(100)}return null}})}
 if(c.id===G.kingId)kingTalk(c,o)}
function tileGate(){return G.sites.some(s=>s.quest==='king'&&dist(G.p.x,G.p.y,s.x,s.y+6)<=3)}
function openKeepGate(){const s=G.sites.find(q=>q.quest==='king');if(s)tset(s.x,s.y+6,'gateopen')}
function kingTalk(c,o){const p=G.p,lr=p.lore.length;if(c.aegis){if(seasonIdx()===3)o.unshift({label:'Speak of the snows',fn:()=>{msg('Vorgath: "She went out in weather like this." He does not seem to see you. You have time.','say');c.truce=G.turn+10;return talkSheet(c)}});o.unshift({label:'"Take off the amulet, Aldric."',fn:()=>{msg(lr?'He flinches at the name. The Aegis flares. "NO." Only the Sundering Amulet will break it.':'He does not know that name, or will not. Learn who he was.','say');advance(100);return null}});return}
 const se=seasonIdx();const pc=clamp(10+lr*15+(se===3?15:0)+(se===1?-10:0)+eff('int')*3+p.speak-(c.annoy||0)*10,5,97);o.unshift({label:'"Your name is Aldric. Mira lived."',sub:pc+'%  (You know '+lr+' of 5 truths)',fn:()=>{G.stats.talks++;if(roll(pc)){msg('The axe slips from his hand. He sits down on the bone throne like an old man.','story');endGame('redemption');return null}c.annoy=(c.annoy||0)+1;msg('Vorgath: "LIES!" He comes at you. Try again if you live.','say');c.alert=2;(c.grudge=c.grudge||{}).p=1;advance(100);return null}});if(G.moraleH<=35)o.unshift({label:'Call on the Horde to depose him',sub:'Morale '+G.moraleH+'. They are ready.',fn:()=>{msg('You raise your voice. Nobody moves to protect him. They take his crown off, carefully, like taking a knife from a child.','story');endGame('mutiny');return null}})}
function riddle(c,onWin){const r=pick(RIDDLES);return{title:'A riddle',text:'"'+r.q+'"',options:r.a.map((a,i)=>({label:a,fn:()=>{if(i===r.c){onWin();return null}msg(SP[c.s].n+': "Wrong." The air goes cold.','warn');c.annoy=(c.annoy||0)+1;c.alert=2;(c.grudge=c.grudge||{}).p=1;advance(100);return null}}))}}
function questOptions(c,o){const d=SP[c.s],p=G.p;const q=G.quests.find(x=>x.from===c.id&&!x.done);if(q){if(q.kind==='gather'&&count(q.item)>=q.n)o.unshift({label:'Hand over '+q.n+' '+ITEMS[q.item].n.toLowerCase(),sub:'Reward: '+q.reward+' coins',fn:()=>{takeItem(q.item,q.n);finishQ(q,c);return talkSheet(c)}});else if(q.kind==='kill'&&q.left<=0)o.unshift({label:'Report that the '+SP[q.s].n.toLowerCase()+'s are dealt with',sub:'Reward: '+q.reward+' coins',fn:()=>{finishQ(q,c);return talkSheet(c)}});return}
 const del=G.quests.find(x=>x.kind==='deliver'&&!x.done&&x.toSite===c.site&&d.tags.leader);if(del&&hasItem('letter'))o.unshift({label:'Deliver the sealed letter',sub:'Reward: '+del.reward+' coins',fn:()=>{takeItem('letter');finishQ(del,c);return talkSheet(c)}});
 if((d.tags.leader||c.s==='farmer'||c.s==='villager'||c.s==='nomad'||c.s==='hunter')&&!c.gaveQ&&G.quests.filter(x=>!x.done).length<4){const se=seasonIdx();o.push({label:'Ask if they need help',fn:()=>{c.gaveQ=1;const q2=genQuest(c,se);G.quests.push(q2);msg(d.n+': "'+q2.say+'"','say');return talkSheet(c)}})}}
function genQuest(c,se){const fac=c.fac;const reward=ri(15,40);if(se===3)return{id:++G.cid,kind:'gather',item:pick(['bread','cooked','turnip']),n:3,from:c.id,fromN:SP[c.s].n,reward:reward+25,fac,say:'We\'re starving. Bring what food you can spare.',t:'Bring food before the village starves'};if(se===2&&chance(.5))return{id:++G.cid,kind:'gather',item:'wood',n:6,from:c.id,fromN:SP[c.s].n,reward,fac,say:'Winter\'s coming. We need firewood.',t:'Bring firewood for the cold'};if(se===1&&fac==='nomad')return{id:++G.cid,kind:'gather',item:'water',n:3,from:c.id,fromN:SP[c.s].n,reward:reward+15,fac,say:'The wells are failing. Bring water.',t:'Bring water to the nomads'};if(se===0&&chance(.5))return{id:++G.cid,kind:'gather',item:'seedwheat',n:2,from:c.id,fromN:SP[c.s].n,reward,fac,say:'Seed was lost in the floods. Bring wheat seed.',t:'Bring seed for planting'};const oth=G.sites.find(s=>s.village&&s.name!==c.site);if(chance(.35)&&oth&&fac==='free'){giveItem(mk('letter'),true);oth.known=1;return{id:++G.cid,kind:'deliver',toSite:oth.name,from:c.id,fromN:SP[c.s].n,reward,fac,say:'Take this to the elder at '+oth.name+'.',t:'Carry a letter to '+oth.name}}const tgt=seasonIdx()===3?'wolf':fac==='nomad'?'scorpion':fac==='hunter'?'spider':'wolf';return{id:++G.cid,kind:'kill',s:tgt,left:3,from:c.id,fromN:SP[c.s].n,reward:reward+15,fac,say:'The '+SP[tgt].n.toLowerCase()+'s are getting bold. Drive them off.',t:'Deal with 3 '+SP[tgt].n.toLowerCase()+'s'}}
function finishQ(q,c){q.done=1;G.p.coins+=q.reward;repGain(q.fac,10);gainXP(15);msg('They press '+q.reward+' coins on you. Word of it travels.','good');story('Helped '+q.fromN+'.',1)}
function questProgress(k,s){G.quests.forEach(q=>{if(q.kind==='kill'&&!q.done&&q.s===s&&q.left>0)q.left--})}
function sunder(c){const p=G.p;p.inv=p.inv.filter(i=>i.k!=='sunder');c.aegis=0;c.stun=4;c.alert=0;G.moraleH=Math.max(0,G.moraleH-20);msg('You raise the amulet. Light pours out of Vorgath, and something screams in a voice that is not his. The Aegis is gone.','story');story('Broke the Aegis of King Vorgath.',5);gainXP(80);advance(100)}
function bindKing(c){takeItem('rope');msg('You bind the sleeping king with rope. His Horde watches, and no one stops you.','story');endGame('captive')}

// ===== INSPECT & TILE ACTIONS =====
function describeC(c){const d=SP[c.s],p=G.p;const b=[d.n];const st=[];if(c.aegis)st.push('wrapped in the Aegis, immune to everything');if(c.sleep>0)st.push(c.ko?'unconscious':(d.tags.hibernate&&seasonIdx()===3?'hibernating':'asleep'));else if(c.alert>=2)st.push('hunting');else if(c.alert===1)st.push('suspicious');else st.push('unaware of you');if(c.para>0)st.push('paralyzed');if(c.confused>0)st.push('confused');if(c.fear>0)st.push('terrified');if(c.burning>0)st.push('on fire');if(c.wet>0)st.push('wet');if(c.stuck>0)st.push('stuck');if(c.charm>0||c.ally)st.push('on your side');if(c.dz==='zombie')st.push('infected with the Grey Walk');if(c.dz==='mania')st.push('consumed by Red Mania');if(c.dz==='cough')st.push('coughing');if(c.hunger>70&&!d.tags.undead)st.push('starving');if(c.gun)st.push('armed with a '+c.gun+' ('+c.ammo+' shots)');if(c.spells)st.push('a caster');if(c.inv.length&&SP[c.s].tags.person)st.push('carrying something');if(c.hp<c.mh)st.push('wounded ('+c.hp+'/'+c.mh+')');return b[0]+': '+st.join(', ')+'.'}
function actionSheetFor(x,y){const p=G.p,k=IX(x,y),d=tdef(x,y),o=[];const near=dist(p.x,p.y,x,y)<=1;const e=at(x,y);const vis=visible(x,y);const self=x===p.x&&y===p.y;let text='';
 if(!L.seen[k])return{title:'Unknown',text:'You have not seen this place.',options:[{label:'Close',fn:()=>null}]};
 if(e&&!isP(e)&&vis&&!(e.hidden&&dist(p.x,p.y,x,y)>1)){text=describeC(e);const dA=SP[e.s];const host=hostile(e,p);const friendly=!host&&dA.tags.person;
  if(dA.tags.talks&&dist(p.x,p.y,x,y)<=2&&e.sleep<=0)o.push({label:'Talk',fn:()=>talkSheet(e),cls:'pri'});
  if(e.id===G.kingId&&e.aegis&&hasItem('sunder')&&dist(p.x,p.y,x,y)<=4)o.unshift({label:'Sunder the Aegis',sub:'Destroy his immortality',cls:'pri',fn:()=>{sunder(e);return null}});
  if(e.id===G.kingId&&!e.aegis&&e.sleep>0&&near&&hasItem('rope'))o.unshift({label:'Bind the king with rope',sub:'End this without blood',cls:'pri',fn:()=>{bindKing(e);return null}});
  if(near&&(unaware(e)))o.push({label:'Stealth kill',sub:stealthPct(e,25)+'%',fn:()=>{doStealthKill(e);return null},cls:'bad'});
  if(near&&unaware(e)&&!dA.tags.undead&&!dA.tags.plant)o.push({label:'Knock out',sub:stealthPct(e,40)+'%, does not kill',fn:()=>{doKnockout(e);return null}});
  if(near&&dA.tags.person&&(e.coins||e.inv.length)&&unaware(e)||near&&dA.tags.person&&friendly&&(e.coins||e.inv.length))o.push({label:'Pickpocket',sub:clamp(Math.round(20+eff('sth')*6+eff('spd')*2+(e.sleep>0?35:0)),5,97)+'%',fn:()=>{doPickpocket(e);return null}});
  if(near&&dA.tags.person)p.inv.filter(i=>idef(i).spike).forEach(i=>o.push({label:'Slip '+idef(i).n.toLowerCase()+' into their drink',fn:()=>{doSpike(e,i.k);return null}}));
  if(near)o.push({label:'Attack',sub:hitChance(p,e)+'% to hit'+(friendly?', a crime':''),cls:friendly?'bad':'',fn:()=>{attackPlayerHit(e);return null}});
  if(canShoot()&&!near||canShoot()&&dist(p.x,p.y,x,y)<=canShoot().rng&&near){const w=canShoot();if(dist(p.x,p.y,x,y)<=w.rng&&los(p.x,p.y,x,y))o.push({label:(w.gun&&!p.loaded&&!w.norld)?'Reload, then you can fire':'Shoot with '+w.n.toLowerCase(),sub:shootPct(e)+'%',fn:()=>{if(w.gun&&!p.loaded&&!w.norld)doReload();else doShoot(x,y);return null}})}
  const fdl=foodList();if(near&&dA.tags.animal&&fdl.length)o.push({label:'Offer food',sub:'Feed twice to tame',fn:()=>feedSheet(e)});
  if(hasItem('rope')&&near&&e.sleep>0&&dA.tags.person&&!dA.tags.unique&&!e.bound)o.push({label:'Tie them up',sub:'Stays out of the fight',fn:()=>{takeItem('rope');e.sleep=9999;e.ko=1;e.bound=1;msg('You bind '+dA.n+'.','good');advance(150);return null}});
  if(RT.act.some(a=>(a.ally||a.charm>0)&&a!==e)&&!e.ally&&!e.charm)o.push({label:'Order your allies to attack',fn:()=>{RT.act.forEach(a=>{if((a.ally||a.charm>0)&&a!==e)a.order=e.id});msg('You point. Your followers move.','good');return null}})}
 else if(self)text=(d.k==='grass'?'':'You stand on '+d.n+'. ')+'Things you can do here:';
 else text='';
 if(!text||!e){const nm=(L.fire[k]?'Burning ':'')+d.n[0].toUpperCase()+d.n.slice(1);if(!e)text=(self?'':nm+'. ')+(self?text:'')}
 if(!self&&!e)o.push({label:'Walk here',fn:()=>({walk:{x,y}}),cls:'pri'});
 // spells & throw at any tile
 const allS=p.spells.concat(p.custom.map(c=>c.id));if(!self&&vis&&allS.length)o.push({label:'Cast a spell here',fn:()=>spellSheetAt(x,y)});
 const th=p.inv.filter(i=>idef(i).k==='throw');if(!self&&vis&&(th.length)&&dist(p.x,p.y,x,y)<=7)o.push({label:'Throw something here',fn:()=>throwSheet(x,y)});
 if(self){if(allS.length)o.push({label:'Cast a spell',fn:()=>spellSheetAt(x,y)})}
 // ground items
 const its=L.items[k];if(its&&its.length&&near){const nc=its.filter(i=>i.k!=='corpse');if(nc.length)o.push({label:'Pick up '+nc.slice(0,2).map(iname).join(', ')+(nc.length>2?'…':''),fn:()=>{if(!self)moveAdjacent(x,y);pickupAll(x,y);return null},cls:'pri'});if(its.some(i=>i.k==='corpse'))o.push({label:'Butcher corpse',sub:'Meat, pelts, bone',fn:()=>{butcher(x,y);return null}})}
 // terrain verbs
 if(near){if(d.link&&d.k==='down'&&self)o.unshift({label:'Climb down',fn:()=>{goLink(x,y);return null},cls:'pri'});if(d.link&&d.k==='up'&&self)o.unshift({label:'Climb out',fn:()=>{goLink(x,y);return null},cls:'pri'});if(d.link&&!self)o.unshift({label:'Walk here to climb '+(d.k==='down'?'down':'up'),fn:()=>({walk:{x,y}}),cls:'pri'});
  if(d.water||d.waterSrc){o.push({label:'Drink',fn:()=>{drinkTile(x,y);return null}});if(hasItem('flask'))o.push({label:'Fill flasks',fn:()=>{fillFlask(x,y);return null}})}
  if(d.chop){const hasAxe=idef(p.eq.w).chop||hasItem('axe');if(hasAxe||d.k!=='hive')o.push({label:'Chop down',sub:hasAxe?'Wood. Loud.':'Slow without an axe, but works',fn:()=>{chopTile(x,y);return null}})}if(d.hive)o.push({label:'Take honey',sub:'Without smoke, the bees will attack',fn:()=>{gatherSmoke(x,y);return null}});
  if(d.mine)o.push({label:'Mine',sub:hasItem('pick')||idef(p.eq.w).minep?'Loud':'Needs a pickaxe',fn:()=>{digTile(x,y);return null}});if(d.forage||d.k==='bush'||d.k==='cactus')o.push({label:'Gather',fn:()=>{forageTile(x,y);return null}});
  if(d.k==='door'){o.push({label:'Open door',fn:()=>{tset(x,y,'dooropen');advance(60);return null}})}if(d.k==='dooropen'&&!at(x,y)){o.push({label:'Close door',fn:()=>{tset(x,y,'door');advance(60);return null}})}if(d.gate||d.k==='locked'){if(hasItem('key_gate')&&d.gate)o.push({label:'Unlock with the key',fn:()=>{useKey(x,y);return null},cls:'pri'});o.push({label:'Pick the lock',sub:clamp(25+eff('sth')*5+eff('agi')*3,10,95)+'%',fn:()=>{lockpickTile(x,y);return null}})}
  if(d.store&&d.k!=='granary'){o.push({label:'Open '+d.n,fn:()=>storeSheet(x,y)})}if(d.k==='granary'){o.push({label:'Raid the granary',fn:()=>storeSheet(x,y)});if(hasItem('flint')||p.torch>0||hasItem('torch'))o.push({label:'Burn the granary',sub:'Horde morale will crash',cls:'bad',fn:()=>{burnGranary(x,y);return null}})}
  if(d.bed&&self)o.push({label:'Sleep',sub:'Rest and heal. Time passes.',fn:()=>{sleepRest(true);return null},cls:'pri'});if(d.forge)o.push({label:'Use the forge',fn:()=>({screen:'forge'}),cls:'pri'});if(d.arcane)o.push({label:'Use the spellforge',fn:()=>({screen:'spellforge'}),cls:'pri'});
  const crop=L.crops[k];if(crop){const def=CROPS[crop.c];const ripe=crop.a>=def.grow;o.push({label:ripe?'Harvest '+def.n:def.n+' growing: '+Math.round(crop.a/def.grow*100)+'%',disabled:!ripe,fn:()=>{harvestCrop(x,y);return null}});if(!ripe&&hasItem('water'))o.push({label:'Water the crop',fn:()=>{waterCrop(x,y);return null}})}if(d.k==='soil'&&!crop)p.inv.filter(i=>idef(i).crop).forEach(i=>o.push({label:'Plant '+idef(i).n.toLowerCase(),fn:()=>{plant(x,y,i);return null}}));
  if(L.fire[k]&&hasItem('water'))o.push({label:'Douse with water',fn:()=>{douse(x,y);return null}});if(d.f&&!L.fire[k]&&(hasItem('flint')||p.torch>0||hasItem('torch')))o.push({label:'Set it on fire',cls:'bad',fn:()=>{ignite(x,y,1);msg('Fire catches.','warn');if(d.wall||d.door||d.indoor)crime('arson',{fac:'free'});advance(100);return null}});if(d.k==='barrel')o.push({label:'Pick up the powder',fn:()=>{tset(x,y,'grass');giveItem(mk('powder'));advance(100);return null}});if(d.k==='thinice'||d.k==='ice'){if(hasItem('flint')||p.torch>0)o.push({label:'Melt the ice',sub:'Whatever is on it goes in',fn:()=>{meltTile(x,y);advance(100);return null}})}
 }
 if(self){const w=canShoot();if(w&&w.gun&&!w.norld&&!p.loaded)o.push({label:'Reload',fn:()=>{doReload();return null}});o.push({label:'Rest 15 turns',fn:()=>{sleepRest(false);return null}});}
 // far barrel shot
 if(!near&&d.boom&&canShoot()&&los(p.x,p.y,x,y)&&dist(p.x,p.y,x,y)<=canShoot().rng)o.unshift({label:'Shoot the powder barrel',cls:'bad',fn:()=>{doShoot(x,y);return null}});
 if(!near&&d.f&&!L.fire[k]&&p.spells.includes('firebolt')&&false){}
 o.push({label:'Close',fn:()=>null});
 return{title:e&&!isP(e)&&vis?SP[e.s].n:(self?G.p.name:(d.n[0].toUpperCase()+d.n.slice(1))),text:text+tileNote(x,y,e),options:o}}
function tileNote(x,y,e){const d=tdef(x,y),k=IX(x,y);const n=[];if(L.fire[k])n.push('It is burning.');const g=L.gas[k];if(g)n.push({smoke:'Thick smoke hangs here.',poison:'Poison gas hangs here.',methane:'Swamp gas hangs here. It will explode if lit.',steam:'Hot steam billows here.',sleepgas:'Sweet purple smoke drifts here.'}[g.k]||'');if(d.k==='thinice')n.push('The channel below is deep.');if(d.k==='tar')n.push('It would burn a long time.');const its=L.items[k];if(its&&!e&&its.length)n.push('Items: '+its.slice(0,4).map(iname).join(', ')+'.');return n.length?' '+n.join(' '):''}
function moveAdjacent(x,y){const p=G.p;if(dist(p.x,p.y,x,y)<=1&&tdef(x,y).p&&!at(x,y)){p.x=x;p.y=y}}
function feedSheet(c){return{title:'Offer food to '+SP[c.s].n,text:'Meat works on predators, anything on grazers. Drugged and poisoned meat work too.',options:foodList().map(f=>({label:iname(f),fn:()=>feedC(c,f)})).concat([{label:'Close',fn:()=>null}])}}
function spellSheetAt(x,y){const p=G.p,o=[];p.spells.forEach(s=>{const d=SPELLS[s];o.push({label:d.n,sub:d.mp+' mana. '+d.d,disabled:p.mp<d.mp,fn:()=>{playerCast(s,d.self?p.x:x,d.self?p.y:y);return null}})});p.custom.forEach(c=>{const cost=customCost(c);o.push({label:c.name,sub:cost+' mana'+(cost>p.mp?' (pays with blood)':'')+'. '+c.fx.map(f=>EFFECTS[f.e].n+' '+f.mag+(f.area?' area '+f.area:'')+(f.dur?' for '+f.dur:'')).join(', '),fn:()=>{castCustom(c,x,y);return null}})});o.push({label:'Close',fn:()=>null});return{title:'Cast a spell',text:p.mp+' of '+p.mmp+' mana.',options:o}}
function throwSheet(x,y){const p=G.p,o=[];p.inv.filter(i=>idef(i).k==='throw').forEach(i=>o.push({label:iname(i),fn:()=>{doThrow(i,x,y);return null}}));o.push({label:'Close',fn:()=>null});return{title:'Throw what?',text:'Stones make noise, and anything nearby comes to look.',options:o}}
function storeSheet(x,y){const k=IX(x,y),st=L.stores[k]=L.stores[k]||[],o=[];const owned=L.id==='world'&&G.sites.some(s=>s.village&&dist(s.x,s.y,x,y)<=s.r);st.forEach(it=>o.push({label:'Take '+iname(it),sub:owned?'Stealing if seen':'',fn:()=>{if(owned)crime('theft',{fac:'free'});if(tdef(x,y).k==='sarc'&&!G.flags.tombOpen2){G.flags.tombOpen2=1;G.flags.tombOpen=G.flags.tombOpen||G.turn;msg('A grey dust rises from the opened coffin and drifts toward the stairs.','warn')}takeStore(x,y,it);return storeSheet(x,y)}}));G.p.inv.filter(i=>idef(i).k!=='quest'&&i!==G.p.eq.w&&i!==G.p.eq.a).slice(0,12).forEach(it=>o.push({label:'Put in '+iname(it),fn:()=>{putStore(x,y,it);return storeSheet(x,y)}}));o.push({label:'Close',fn:()=>null});return{title:tdef(x,y).n,text:st.length?'':'Empty.',options:o}}

// ===== SAVE =====
const SAVEKEY='aegis-of-the-mad-king-v1';
function serial(){return JSON.stringify(G)}
function saveGame(){if(!G||G.over)return;try{localStorage.setItem(SAVEKEY,serial())}catch(e){}}
function deleteSave(){try{localStorage.removeItem(SAVEKEY)}catch(e){}}
function hasSave(){try{return !!localStorage.getItem(SAVEKEY)}catch(e){return false}}
function loadFrom(str){G=JSON.parse(str);L=G.levels[G.p.lv];const p=G.p;const fix=it=>{};p.eq.w=p.eq.w?(p.inv.find(i=>i.k===p.eq.w.k&&JSON.stringify(i.x)===JSON.stringify(p.eq.w.x))||null):null;p.eq.a=p.eq.a?(p.inv.find(i=>i.k===p.eq.a.k&&JSON.stringify(i.x)===JSON.stringify(p.eq.a.x))||null):null;rebuild();computeFOV();return G}
function loadGame(){try{const s=localStorage.getItem(SAVEKEY);if(!s)return false;loadFrom(s);return true}catch(e){return false}}
const ENDINGS={conquest:{t:'The King Is Dead',d:'You killed Vorgath on his bone throne. The Horde scatters into a hundred warlords.'},fallen:{t:'The King Fell',d:'Vorgath died without your hand on the blade. The mountain is quiet, and the continent wonders who to thank.'},redemption:{t:'Aldric',d:'You told him the truth and he believed it. He walks south in the first thaw to find a grave in the desert, and the Horde goes home. Nobody had to die for this.'},mutiny:{t:'The Bloodless Crown',d:'The Horde deposed its own king. Soldiers who had been starving went back to their farms. They still talk about the stranger who fed them.'},captive:{t:'Rope and Quiet',d:'You bound the sleeping king and carried him out of his own hall. He stands trial in the spring, and he is the last to be sentenced to anything.'},puppet:{t:'The New Voice',d:'He lives. He rules. He says whatever you think. The Aegis was only ever a first draft of this.'},death:{t:'You Died',d:''}};
